{"path": "zipper.py", "content": "class Zipper:
    """A purely functional zipper over binary trees.

    Trees are dicts of the form {"value": v, "left": tree|None, "right": tree|None}.
    The zipper holds the focused subtree and a breadcrumb trail of
    (direction, parent_value, other_subtree) tuples leading back to the root.
    """

    def __init__(self, tree, path=()):
        self._tree = tree
        self._path = path

    @staticmethod
    def from_tree(tree):
        return Zipper(tree, ())

    def value(self):
        return self._tree["value"]

    def set_value(self, value):
        return Zipper(
            {"value": value, "left": self._tree["left"], "right": self._tree["right"]},
            self._path,
        )

    def left(self):
        child = self._tree["left"]
        if child is None:
            return None
        crumb = ("left", self._tree["value"], self._tree["right"])
        return Zipper(child, self._path + (crumb,))

    def set_left(self, tree):
        return Zipper(
            {"value": self._tree["value"], "left": tree, "right": self._tree["right"]},
            self._path,
        )

    def right(self):
        child = self._tree["right"]
        if child is None:
            return None
        crumb = ("right", self._tree["value"], self._tree["left"])
        return Zipper(child, self._path + (crumb,))

    def set_right(self, tree):
        return Zipper(
            {"value": self._tree["value"], "left": self._tree["left"], "right": tree},
            self._path,
        )

    def up(self):
        if not self._path:
            return None
        direction, value, other = self._path[-1]
        if direction == "left":
            parent = {"value": value, "left": self._tree, "right": other}
        else:
            parent = {"value": value, "left": other, "right": self._tree}
        return Zipper(parent, self._path[:-1])

    def to_tree(self):
        zipper = self
        while zipper._path:
            zipper = zipper.up()
        return zipper._tree

    def __eq__(self, other):
        if not isinstance(other, Zipper):
            return NotImplemented
        return self._tree == other._tree and self._path == other._path

    def __repr__(self):
        return f"Zipper({self._tree!r}, {self._path!r})"
"}

{"path": "zipper_test.py", "content": "import unittest

from zipper import Zipper


def leaf(v):
    return {"value": v, "left": None, "right": None}


TREE = {
    "value": 1,
    "left": {"value": 2, "left": None, "right": leaf(3)},
    "right": leaf(4),
}


class ZipperTest(unittest.TestCase):
    def test_round_trip(self):
        self.assertEqual(Zipper.from_tree(TREE).to_tree(), TREE)

    def test_navigation(self):
        z = Zipper.from_tree(TREE)
        self.assertEqual(z.left().right().value(), 3)
        self.assertEqual(z.left().right().up().up().value(), 1)
        self.assertIsNone(z.left().left())
        self.assertIsNone(z.up())

    def test_traversing_up_from_top(self):
        self.assertIsNone(Zipper.from_tree(TREE).up())

    def test_set_value(self):
        t = Zipper.from_tree(TREE).left().set_value(5).to_tree()
        self.assertEqual(t["left"]["value"], 5)
        self.assertEqual(TREE["left"]["value"], 2)

    def test_set_value_after_up(self):
        t = Zipper.from_tree(TREE).left().right().up().set_value(5).to_tree()
        self.assertEqual(t["left"]["value"], 5)
        self.assertEqual(t["left"]["right"], leaf(3))

    def test_set_left_and_right(self):
        z = Zipper.from_tree(TREE).left().set_left(leaf(5)).set_right(None)
        t = z.to_tree()
        self.assertEqual(t["left"], {"value": 2, "left": leaf(5), "right": None})
        t2 = Zipper.from_tree(TREE).set_right(leaf(6)).to_tree()
        self.assertEqual(t2["right"], leaf(6))

    def test_different_paths_same_node(self):
        a = Zipper.from_tree(TREE).left().up().right()
        b = Zipper.from_tree(TREE).right()
        self.assertEqual(a, b)


if __name__ == "__main__":
    unittest.main()
"}
